'use strict';
(()=>{
  const T=window.Tactical,$=s=>document.querySelector(s),copy=x=>JSON.parse(JSON.stringify(x));
  let battle=null,run=null,selected=null,target=null,busy=false,speed=1,visual=[],animation=null,particles=[],reward=null,replacement=null,token=0,toastTimer,displaySnapshot=null;
  const canvas=$('#battlefield'),ctx=canvas.getContext('2d');let width=0,height=0;
  function toast(msg){$('#toast').textContent=msg;$('#toast').style.display='block';clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').style.display='none',2400);}
  function cardHtml(c,attrs=''){const d=T.definition(c),trait=T.traits[d.trait];return `<button class="card ${attrs.includes('reward')?'reward-card':''}" style="--trait:${trait.color}" ${attrs}><span class="card-head"><span class="card-owner">${d.actor==='doyun'?'도윤':'하린'}${c.upgraded?' · 진화':''}</span><span class="cost">${d.cost}</span></span><span class="card-art" aria-hidden="true">${d.art}</span><span class="card-name">${d.name}</span><span class="card-desc">${T.description(c)}</span><span class="tag">◆ ${trait.name}</span></button>`;}
  function portrait(a){
    const ally=a.side===0,hair=a.id==='doyun'?'#273e55':'#5c3c42';
    const body=ally?`<path d="M6 46L11 30 24 26 37 30 43 46" fill="${a.color}"/><ellipse cx="24" cy="19" rx="9" ry="12" fill="#d7c5bc"/><path d="M14 22L13 11 21 5 32 8 36 19 29 18 24 12 18 24 ${a.id==='doyun'?'13 37 8 33':'36 35 42 30'}Z" fill="${hair}"/><path d="M29 20h3" stroke="#302c37" stroke-width="2"/>`:`<path d="M7 46L12 30 24 26 36 30 42 46" fill="${a.color}"/><path d="M13 13L24 6 35 13 33 26 24 31 15 26Z" fill="#756a7d"/><path d="M16 18h16l-4 6h-8Z" fill="#30293b"/><path d="M18 20h4m4 0h4" stroke="#ffc1ca" stroke-width="2"/>${a.type==='boss'?'<circle cx="24" cy="19" r="17" fill="none" stroke="#c7a9f1"/>':a.type==='rear'||a.type==='front'?'<path d="M10 8l14-6 14 6" fill="none" stroke="#d1a5ec" stroke-width="3"/>':a.type==='healer'?'<path d="M24 35v8m-4-4h8" stroke="#9ee7c7" stroke-width="3"/>':'<path d="M6 44L39 10" stroke="#e5c39c" stroke-width="2"/>'}`;
    return `<svg viewBox="0 0 48 48" aria-hidden="true"><rect width="48" height="48" rx="6" fill="#182330"/>${body}</svg>`;
  }
  function name(id){return battle?.get(id)?.name||id;}
  function startScreen(){token++;busy=false;battle=null;run=null;selected=null;animation=null;visual=[];$('#overlay').hidden=false;$('#overlay').innerHTML=`<div class="sheet"><span class="eyebrow">새 전투 방향 · 플레이 가능한 첫 실험</span><h1>카드로 만드는 교전</h1><p>도윤의 결속과 견인, 하린의 공격을 직접 선택하세요.<br>준비된 캐릭터의 카드 한 장 또는 기본행동을 선택하세요.<br>선택 중 게이지는 정지하며 적은 자신의 차례에 예고를 실행합니다.</p><div class="start-options"><button class="start-option" data-start="balanced"><strong>균형 출발</strong><span>개인 턴에서 공격과 보호를 시험합니다.<br>처음 플레이할 때 추천.</span></button><button class="start-option" data-start="attack"><strong>공격 출발</strong><span>개인 덱 전환 전의 비교용 구성입니다.<br>처치로 적의 행동을 없애세요.</span></button><button class="start-option" data-start="protect"><strong>보호 출발</strong><span>1단계 고정 선택지는 모든 출발에서 같습니다.<br>공격 기회를 언제 잡을지 판단하세요.</span></button></div><div class="sheet-footer"><span class="eyebrow">1단계 · 개인 게이지 · 고정 선택지 · 1턴 1행동 · 비용 한도 2</span><a href="character.html?v=serinlook1">기존 풀오토와 비교</a></div><p>캐릭터·그림·능력 수치는 테스트용입니다. 이 원정은 저장되지 않으며, 기존 저장과 연결되지 않습니다.</p></div>`;render();}
  function newRun(style){token++;run={style,deck:T.starter(style),stage:0,hp:{doyun:40,harin:44},results:[],choices:[]};beginBattle();}
  function beginBattle(){battle=new T.Battle({cards:run.deck,stage:run.stage,hp:run.hp,seed:137+run.stage*977});visual=copy(battle.s.actors);selected=null;target=null;busy=false;animation=null;particles=[];$('#overlay').hidden=true;$('#skill-banner').classList.remove('show');render();}
  function render(){
    const s=busy&&displaySnapshot?displaySnapshot:battle?.s;const view=busy&&displaySnapshot?T.Battle.restore({...displaySnapshot,actors:visual}):battle;$('#stage-name').textContent=s?`${s.stage+1} / 3 · ${T.encounters[s.stage].name}`:'카드로 만드는 교전';$('#round-label').textContent='';
    $('#energy').textContent=s&&s.phase==='choice'?view.get(s.current)?.name||'':'';
    $('#phase-label').textContent='';$('#end-turn').disabled=!s||busy||s.phase!=='choice';
    $('#turn-order').innerHTML=s?view.nextOrder().map((p,i)=>{const a=view.get(p.actor);return `<div class="turn-entry ${p.current?'current':''} ${a.side?'enemy':'ally'}" data-order-actor="${a.id}" style="--unit:${a.color}" title="${a.name} · 행동 시각 ${p.tick} · 게이지 ${a.gauge}/100" aria-label="${i+1}번째 ${a.name}${p.current?' 현재 행동자':''}"><span class="turn-portrait">${portrait(a)}</span><span class="turn-name">${a.name}</span>${p.current?'<span class="turn-pointer" aria-hidden="true">▶</span>':''}</div>`;}).join(''):'';
    $('#hand').innerHTML=s?s.hand.map(c=>{const d=T.definition(c);return cardHtml(c,`data-card="${c.id}" aria-label="${d.name}, ${d.cost} 행동력, ${T.traits[d.trait].name}" ${busy||s.phase!=='choice'||s.energy<d.cost?'disabled':''}`);}).join(''):'';
    if(selected)document.querySelector(`[data-card="${selected}"]`)?.classList.add('selected');
    $('#enemy-intents').innerHTML=s?s.intents.map(p=>{const a=view.get(p.actor);return `<div class="intent ${a.hp<=0?'dead':''}"><strong>${a.name}</strong><span>${view.intentText(p)}</span><small>HP ${a.hp}/${a.max}${a.bound?' · 결속':''}</small></div>`;}).join(''):'';
    $('#selection').hidden=!selected||busy;
    if(selected&&!busy){const c=s.hand.find(c=>c.id===selected);if(!c){selected=null;$('#selection').hidden=true;}else{const d=T.definition(c);$('#selected-description').textContent=d.name;$('#targets').innerHTML=battle.targets(c).map(id=>{const a=battle.get(id);return `<button data-target="${id}" class="${target===id?'chosen':''}">${a.name} · ${a.side===0?(a.lane==='front'?'전열':'후열'):'적'} · HP ${a.hp}${d.kind==='move'?' → '+(a.lane==='front'?'후열':'전열'):''}</button>`;}).join('');$('#play-card').disabled=!battle.check(selected,target).ok;
      $('#preview-result').textContent=target?'':'대상 선택';}}
    $('#game').style.setProperty('--command-height',`${$('#command').getBoundingClientRect().height}px`);
  }
  function selectCard(id){if(busy||battle?.s.phase!=='choice')return;const c=battle.s.hand.find(c=>c.id===id);if(!c)return;selected=selected===id?null:id;target=null;if(selected){const ts=battle.targets(c);if(T.definition(c).target==='self'||ts.length===1)target=ts[0];}render();}
  function delay(ms){return new Promise(resolve=>setTimeout(resolve,ms));}
  async function animate(events,ownToken){for(const e of events){if(ownToken!==token)return;if(speed===0){applyVisual(e);continue;}const from=visual.find(a=>a.id===e.from),to=visual.find(a=>a.id===e.to);const duration=(e.kind==='cast'?650:e.kind==='basic'||e.kind==='enemy'?370:e.kind==='cancel'?110:320)/speed;
      animation={e,from:from?position(from):null,to:to?position(to):null,moveFrom:e.kind==='move'&&to?position(to):['advance','return'].includes(e.kind)&&from?position(from):null,moveTo:e.kind==='move'&&to?position({...to,lane:e.lane}):['advance','return'].includes(e.kind)&&from?position({...from,acting:e.kind==='advance'}):null,start:performance.now(),duration};
      if(['cast','basic','enemy'].includes(e.kind)){$('#skill-banner').innerHTML=`<small>${name(e.from)}</small>${e.name}`;$('#skill-banner').classList.add('show');}
      await delay(duration*.6);if(ownToken!==token)return;applyVisual(e);await delay(duration*.4);if(ownToken!==token)return;
    }animation=null;$('#skill-banner').classList.remove('show');}
  function applyVisual(e){const actor=visual.find(a=>a.id===e.from);if(actor&&e.kind==='advance')actor.acting=true;if(actor&&e.kind==='return')actor.acting=false;const a=visual.find(a=>a.id===e.to);if(a){if(e.hp!==undefined)a.hp=e.hp;if(e.shield!==undefined)a.shield=e.shield;if(e.lane)a.lane=e.lane;if(e.kind==='bind'){a.bound=.5;a.boost=e.boost;}if(['hit','heal','shield'].includes(e.kind)){const p=position(a);particles.push({x:p.x,y:p.y-110*p.scale,text:e.kind==='hit'?(e.amount?'-'+e.amount:'방어'):'+'+(e.amount||0),color:e.kind==='hit'?'#ffb2b9':'#a9f0d6',start:performance.now()});}}if(busy)render();}
  async function useCard(){if(busy||!battle||!selected)return;const before=battle.snapshot(),r=battle.play(selected,target);if(!r.ok){toast(r.error);return;}busy=true;selected=null;target=null;displaySnapshot=before;visual=copy(before.actors);const ownToken=token;render();await animate(r.events,ownToken);if(ownToken!==token)return;visual=copy(battle.s.actors);busy=false;displaySnapshot=null;render();finishIfNeeded();}
  async function endTurn(){if(busy||!battle||battle.s.phase!=='choice')return;const before=battle.snapshot(),r=battle.endTurn();busy=true;selected=null;target=null;displaySnapshot=before;visual=copy(before.actors);const ownToken=token;render();await animate(r.events,ownToken);if(ownToken!==token)return;visual=copy(battle.s.actors);busy=false;displaySnapshot=null;render();finishIfNeeded();}
  function finishIfNeeded(){if(!['won','lost'].includes(battle.s.phase))return;const s=battle.s;run.hp=Object.fromEntries(battle.alive(0).map(a=>[a.id,a.hp]));for(const id of ['doyun','harin'])run.hp[id]??=0;run.results.push({stage:s.stage,round:s.round,stats:copy(s.stats),hp:copy(run.hp)});selected=null;reward=null;replacement=null;
    if(s.phase==='lost'||run.stage===2){$('#overlay').hidden=false;const totals=run.results.reduce((n,r)=>{for(const k of Object.keys(r.stats))n[k]=(n[k]||0)+r.stats[k];return n;},{});$('#overlay').innerHTML=`<div class="sheet"><span class="eyebrow">${s.phase==='won'?'원정 완료':'원정 종료'}</span><h1>${s.phase==='won'?'세 번의 교전을 넘었습니다.':'다른 선택으로 다시 도전하세요.'}</h1><p>${s.phase==='won'?'개인 게이지와 1턴 1행동으로 만든 결과입니다. 개인 덱과 손패는 2단계에서 검증합니다.':'현재 행동자의 선택지에서 적을 먼저 처치할지, 피해를 막을지 다시 판단해보세요.'}</p><div class="result-stat"><span>개인 턴 ${run.results.reduce((n,r)=>n+r.round,0)}회</span><span>카드 ${totals.cards}장</span><span>기술 피해 ${totals.cardDamage}</span><span>기본 피해 ${totals.basicDamage}</span><span>보호 ${totals.blocked}</span><span>회복 ${totals.healing}</span><span>이동 ${totals.moves}회</span></div><p>${run.choices.length?'이번 성장: '+run.choices.join(' → '):'첫 전투에서 출발 덱의 역할을 확인했습니다.'}</p><button data-home>다시 시작</button></div>`;
    }else rewardScreen();
  }
  function rewardScreen(){const hp=battle.alive(0).map(a=>`${a.name} HP ${a.hp}/${a.max}`).join(' · ');$('#overlay').hidden=false;$('#overlay').innerHTML=`<div class="sheet"><span class="eyebrow">${run.stage+1}번째 전투 승리 / 다음 ${T.encounters[run.stage+1].name}</span><h2>다음 전투의 해법을 고르세요.</h2><p>${hp}<br>${T.encounters[run.stage+1].hint}</p><div class="rewards">${['burst','shelter','reunion'].filter(key=>run.hp[T.cards[key].actor]>0).map(key=>cardHtml({id:'reward-'+key,key},`data-reward="${key}"`)).join('')}</div><p>보상 카드를 얻으려면 기존 12장 중 한 장을 교체합니다. 선택한 카드는 이번 원정에서만 남습니다.</p><div class="sheet-footer"><button data-rest>카드 대신 휴식 · 생존자 HP +8</button><span class="eyebrow">다음 전투부터 소유자의 고정 선택지에 추가</span></div></div>`;}
  function selectReward(key){if(!['burst','shelter','reunion'].includes(key))return;reward=key;replacement=null;const groups=[];for(const c of run.deck){const group=groups.find(x=>x.card.key===c.key&&!!x.card.upgraded===!!c.upgraded);if(group)group.count++;else groups.push({card:c,count:1});}$('#overlay').innerHTML=`<div class="sheet"><span class="eyebrow">보상 교체 / 덱 12장 유지</span><h2>${T.cards[key].name} 대신 어떤 카드를 뺄까요?</h2><div class="comparison">새 카드 · ${T.cards[key].actor==='doyun'?'도윤':'하린'} / ${T.traits[T.cards[key].trait].name} / 행동력 ${T.cards[key].cost}<br>${T.description({key})}</div><div class="replace-list">${groups.map(({card:c,count})=>{const d=T.definition(c);return `<button class="replace-option" data-replace="${c.id}"><strong>${d.name} · ${d.cost} · ${count}장</strong><span>${d.actor==='doyun'?'도윤':'하린'} / ${T.traits[d.trait].name}<br>${T.description(c)}</span></button>`;}).join('')}</div><div id="replace-comparison" class="comparison">같은 카드는 묶어서 표시합니다. 선택한 카드 한 장만 교체됩니다.</div><div class="sheet-footer" style="margin-top:16px"><button data-reward-back>뒤로</button><button id="confirm-reward" disabled>교체하고 다음 전투</button></div></div>`;}
  function chooseReplacement(id){const c=run.deck.find(x=>x.id===id);if(!c)return;replacement=id;document.querySelectorAll('[data-replace]').forEach(b=>b.classList.toggle('chosen',b.dataset.replace===id));const old=T.definition(c),next=T.cards[reward];$('#replace-comparison').textContent=`${old.name} (${old.cost}, ${T.traits[old.trait].name}) → ${next.name} (${next.cost}, ${T.traits[next.trait].name}). ${T.description(c)} → ${T.description({key:reward})}`;$('#confirm-reward').disabled=false;}
  function nextBattle(rest=false){if(!run||battle.s.phase!=='won'||run.stage>=2)return;if(rest){for(const id of ['doyun','harin'])if(run.hp[id]>0)run.hp[id]=Math.min(id==='doyun'?40:44,run.hp[id]+8);run.choices.push('휴식');}else{if(!reward||!replacement)return;const index=run.deck.findIndex(c=>c.id===replacement);if(index<0)return;run.deck[index]={id:`reward-${run.stage}-${reward}`,key:reward,upgraded:false};run.choices.push(T.cards[reward].name);}run.stage++;beginBattle();}
  function resize(){width=innerWidth;height=innerHeight;const dpr=Math.min(devicePixelRatio||1,2);canvas.width=Math.round(width*dpr);canvas.height=Math.round(height*dpr);ctx.setTransform(dpr,0,0,dpr,0,0);if($('#command'))$('#game').style.setProperty('--command-height',`${$('#command').getBoundingClientRect().height}px`);}
  function position(a){return window.TacticalStage.project(a,visual,width,height,$('#command').getBoundingClientRect().height);}
  function draw(time){particles=particles.filter(p=>time-p.start<950);const intents=battle?(busy&&displaySnapshot?displaySnapshot:battle.s).intents.filter(p=>visual.find(a=>a.id===p.actor)?.hp>0):[];window.TacticalStage.draw(ctx,{width,height,dock:$('#command').getBoundingClientRect().height,actors:visual,animation,particles,intents,time,cards:T.cards});requestAnimationFrame(draw);}
  document.addEventListener('click',e=>{const button=e.target.closest('button');if(!button||button.disabled)return;const d=button.dataset;if(d.start)newRun(d.start);else if(d.card)selectCard(d.card);else if(d.target&&!busy){target=d.target;render();}else if(d.reward)selectReward(d.reward);else if(d.replace)chooseReplacement(d.replace);else if('rest'in d)nextBattle(true);else if('rewardBack'in d)rewardScreen();else if('home'in d)startScreen();else if(button.id==='confirm-reward')nextBattle();});
  $('#play-card').addEventListener('click',useCard);$('#end-turn').addEventListener('click',endTurn);$('#cancel').addEventListener('click',()=>{selected=null;target=null;render();});$('#restart').addEventListener('click',()=>{if(busy)return;startScreen();});$('#speed').addEventListener('click',()=>{speed=speed===1?2:speed===2?0:1;$('#speed').textContent=speed?`연출 ${speed}×`:'연출 끔';});$('#help-toggle').addEventListener('click',()=>$('#help').hidden=!$('#help').hidden);$('#help-close').addEventListener('click',()=>$('#help').hidden=true);
  document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!busy){selected=null;target=null;$('#help').hidden=true;render();}});addEventListener('resize',resize);resize();requestAnimationFrame(draw);startScreen();
  window.tacticalGame={get battle(){return battle;},get run(){return run;},get busy(){return busy;},newRun,endTurn,selectCard,useCard,get selected(){return selected;},setTarget(id){target=id;render();},get speed(){return speed;}};
})();
